<section class="page-section"><div class="container narrow"><div class="section-title"><h1><?= e(__($title)) ?></h1><a class="btn btn-ghost" href="<?= e(url('/admin')) ?>"><?= e(__('Quay lại quản trị')) ?></a></div><p><?= e(__('“Ngừng sử dụng” chỉ ẩn mục này khỏi các lựa chọn mới; tin đã đăng vẫn giữ nguyên. Có thể kích hoạt lại.')) ?></p>
<?php foreach($catalogs as $kind=>$items): ?><section class="surface-card mb-4"><h2><?= e($kind==='type'?__('Loại chỗ ở'):__('Tiện nghi')) ?></h2>
<?php foreach(array_merge([['id'=>0,'name'=>'','detail'=>'','is_active'=>1]],$items) as $item): $retired=$item['id'] && !$item['is_active']; if($old && $old['kind']===$kind && $old['id']===(int)$item['id']) { $item=array_merge($item,['name'=>$old['name'],'detail'=>$old['detail'],'is_active'=>$old['active']]); } ?>
<form class="border-top py-3" method="post" action="<?= e(url('/admin/catalog')) ?>"><?= csrf_field() ?><input type="hidden" name="kind" value="<?= $kind ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><h3 class="h6"><?= $item['id']?'#'.(int)$item['id']:e(__('Thêm mới')) ?><?php if($retired): ?> <span class="status status-cancelled"><?= e(__('Đã ngừng sử dụng')) ?></span><?php endif; ?></h3>
<label for="catalog-name-<?= $kind ?>-<?= (int)$item['id'] ?>"><?= e(__('Tên')) ?></label><input class="form-control mb-2" id="catalog-name-<?= $kind ?>-<?= (int)$item['id'] ?>" name="name" value="<?= e($item['name']) ?>" maxlength="80" required>
<label for="catalog-detail-<?= $kind ?>-<?= (int)$item['id'] ?>"><?= e($kind==='type'?__('Mô tả'):__('Mã icon (không bắt buộc)')) ?></label><input class="form-control mb-2" id="catalog-detail-<?= $kind ?>-<?= (int)$item['id'] ?>" name="detail" value="<?= e($item['detail']) ?>" maxlength="<?= $kind==='type'?5000:80 ?>">
<label><input type="checkbox" name="active" value="1" <?= $item['is_active']?'checked':'' ?>> <?= e(__('Đang sử dụng')) ?></label><?php if($retired): ?><small class="form-text text-muted mb-2"><?= e(__('Mục này đang ẩn khỏi các lựa chọn mới. Để kích hoạt lại, đánh dấu “Đang sử dụng” rồi bấm “Lưu thay đổi”.')) ?></small><?php endif; ?><div class="action-row"><button class="btn btn-primary"><?= e($item['id']?__('Lưu thay đổi'):__('Thêm danh mục')) ?></button><?php if($item['id'] && !$retired): ?><button class="btn btn-outline-danger" name="active" value="0" data-confirm="<?= e(__('Ngừng sử dụng danh mục này? Các tin hiện có vẫn được giữ.')) ?>"><?= e(__('Ngừng sử dụng')) ?></button><?php endif; ?></div></form>
<?php endforeach; ?></section><?php endforeach; ?></div></section>
